  const p = join(root, name, 'trajectories.jsonl')
  if (!existsSync(p)) continue
  const lines = readFileSync(p, 'utf8').split('\n').filter(Boolean)
  for (const line of lines) {
    const t = JSON.parse(line)
    const k = Object.keys(t).sort().join(',')
