    keysets.get(k).push(name)
    const b = `${t.reward?.basis}/${JSON.stringify(t.reward?.value)}/outcome=${JSON.stringify(t.reward?.outcome)}`
    rewardBases.set(b, (rewardBases.get(b) ?? 0) + 1)
    formats.set(t.format, (formats.get(t.format) ?? 0) + 1)
  }
}
console.log('--- formats ---'); console.log([...formats])
console.log('--- keysets ---')
for (const [k, recs] of keysets) console.log(`${recs.length}x [${[...new Set(recs)].slice(0,3).join(', ')}${new Set(recs).size>3?', …':''}]\n   ${k}`)
console.log('--- reward basis/value ---')
for (const [b, n] of [...rewardBases].sort()) console.log(`${n}\t${b}`)
