import { readdirSync, readFileSync, existsSync } from 'node:fs'
import { join } from 'node:path'
const root = 'data/proving-ground'
const ids = new Map()
const held = new Map()
const impl = new Map()
const groups = new Set()
const envIds = new Map()
const withUsage = { steps: 0, stepsWithUsage: 0, trajWithAnyUsage: 0, trajNoSteps: 0 }
let total = 0
const heldOutTaskIds = new Set()
const taskRoot = 'examples/headless-agent/tests/fixtures/proving-ground-bench/environments'
for (const t of readdirSync(taskRoot)) {
  const j = JSON.parse(readFileSync(join(taskRoot, t, 'task.json'), 'utf8'))
  if (j.heldOut) heldOutTaskIds.add(j.id)
}
console.log('held-out task.json ids:', [...heldOutTaskIds].sort().join(', ') || '(none)')
for (const name of readdirSync(root).sort()) {
  if (['folds', 'datasets', 'tools'].includes(name)) continue
  const p = join(root, name, 'trajectories.jsonl')
  if (!existsSync(p)) continue
  for (const line of readFileSync(p, 'utf8').split('\n').filter(Boolean)) {
    const t = JSON.parse(line)
    total += 1
    ids.set(t.id, (ids.get(t.id) ?? 0) + 1)
    const e = t.environment
    held.set(String(e?.heldOut), (held.get(String(e?.heldOut)) ?? 0) + 1)
    impl.set(e?.implementer ?? '(absent)', (impl.get(e?.implementer ?? '(absent)') ?? 0) + 1)
    if (e?.group) groups.add(e.group)
    envIds.set(e?.environmentId ?? '(none)', (envIds.get(e?.environmentId ?? '(none)') ?? 0) + 1)
    withUsage.steps += t.steps.length
    withUsage.stepsWithUsage += t.steps.filter(s => s.usage).length
    if (t.steps.some(s => s.usage)) withUsage.trajWithAnyUsage += 1
    if (t.steps.length === 0) withUsage.trajNoSteps += 1
  }
}
console.log('total', total, 'unique ids', ids.size, 'duplicated ids', [...ids].filter(([, n]) => n > 1).length)
console.log('heldOut:', [...held])
console.log('implementer:', [...impl])
console.log('groups sample:', [...groups].slice(0, 8), 'count', groups.size)
console.log('usage:', withUsage)
console.log('env ids:', [...envIds].sort((a, b) => a[0].localeCompare(b[0])).map(([k, v]) => `${k}=${v}`).join(' '))

