import { readdirSync, readFileSync, existsSync } from 'node:fs'
import { join } from 'node:path'
const root = 'data/proving-ground'
const taskRoot = 'examples/headless-agent/tests/fixtures/proving-ground-bench/environments'
const tasks = new Map()
for (const t of readdirSync(taskRoot)) {
  const j = JSON.parse(readFileSync(join(taskRoot, t, 'task.json'), 'utf8'))
  tasks.set(j.id, { tier: j.tier, domain: j.domain, heldOut: j.heldOut })
}
console.log('bench task ids:', [...tasks.keys()].sort().join(' '))
const byImpl = new Map()
const dupes = new Map()
const seen = new Map()
const missingTask = new Set()
for (const name of readdirSync(root).sort()) {
  if (['folds', 'datasets', 'tools'].includes(name)) continue
  const p = join(root, name, 'trajectories.jsonl')
  if (!existsSync(p)) continue
  for (const line of readFileSync(p, 'utf8').split('\n').filter(Boolean)) {
    const t = JSON.parse(line)
    const e = t.environment
    const impl = e?.implementer ?? '(absent)'
    const k = `${impl} steps=${t.steps.length === 0 ? '0' : '>0'} msgs=${t.messages.length === 0 ? '0' : '>0'}`
    byImpl.set(k, (byImpl.get(k) ?? 0) + 1)
    if (e?.environmentId && !tasks.has(e.environmentId)) missingTask.add(e.environmentId)
    if (seen.has(t.id)) dupes.set(t.id, [seen.get(t.id), name])
    else seen.set(t.id, name)
  }
}
console.log('--- implementer x steps x messages ---')
for (const [k, v] of [...byImpl].sort()) console.log(v, k)
console.log('--- env ids with no task.json ---', [...missingTask].sort().join(' '))
console.log('--- duplicate ids (first record, later record) ---', dupes.size)
for (const [id, where] of [...dupes].slice(0, 30)) console.log(' ', id.slice(0, 44), where.join(' -> '))

