import { readdirSync, readFileSync, existsSync } from 'node:fs'
import { join } from 'node:path'
const SECRET_PATTERNS = [
  { name: 'anthropic-key', re: /sk-ant-[A-Za-z0-9_-]{20,}/g },
  { name: 'openai-style-key', re: /\bsk-(?:proj-)?[A-Za-z0-9]{20,}/g },
  { name: 'github-token', re: /\b(?:ghp|gho|ghu|ghs|ghr)_[A-Za-z0-9]{30,}|\bgithub_pat_[A-Za-z0-9_]{20,}/g },
  { name: 'aws-access-key', re: /\bAKIA[0-9A-Z]{16}\b/g },
  { name: 'slack-token', re: /\bxox[abprs]-[A-Za-z0-9-]{10,}/g },
  { name: 'private-key', re: /-----BEGIN [A-Z ]*PRIVATE KEY-----/g },
  { name: 'bearer-token', re: /\bBearer [A-Za-z0-9._~+/=-]{20,}/g },
  { name: 'email-address', re: /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g },
]
const root = 'data/proving-ground'
const hits = new Map()
const armCount = new Map()
function armOf(group) {
  if (group === undefined) return '-'
  const experiment = /^experiment-[0-9a-f]+-(baseline|candidate)$/.exec(group)
  return experiment ? experiment[1] : group.replace(/^fleet-[0-9a-f-]+$/, 'fleet')
}
for (const name of readdirSync(root).sort()) {
  if (['folds', 'datasets', 'tools'].includes(name)) continue
  const p = join(root, name, 'trajectories.jsonl')
  if (!existsSync(p)) continue
  for (const line of readFileSync(p, 'utf8').split('\n').filter(Boolean)) {
    const t = JSON.parse(line)
    const a = armOf(t.environment?.group)
    armCount.set(a, (armCount.get(a) ?? 0) + 1)
